package com.myles.cijian;

import android.app.*;import android.content.*;import android.os.*;import android.view.*;import android.widget.*;import java.lang.reflect.*;import java.util.*;

/** 专用模拟器：整页横滑、点击隔离、按钮间距及语音设置往返。 / Emulator-only full-page gestures, click isolation, action gaps and voice-settings return. */
public final class Feature1105Tests extends Instrumentation {
    private BrowseActivity activity;private int checks;private long down;private String language;
    @Override public void onCreate(Bundle args){super.onCreate(args);language=args==null?"ZH":args.getString("language","ZH");start();}
    private void check(boolean ok,String label){if(!ok)throw new AssertionError(label);checks++;}
    private void ui(Runnable action){java.util.concurrent.atomic.AtomicReference<Throwable> error=new java.util.concurrent.atomic.AtomicReference<>();runOnMainSync(()->{try{action.run();}catch(Throwable e){error.set(e);}});if(error.get()!=null)throw new AssertionError("UI assertion",error.get());}
    private Object field(Object target,String name){try{Field f=target.getClass().getDeclaredField(name);f.setAccessible(true);return f.get(target);}catch(Exception e){throw new RuntimeException(e);}}
    private LinearLayout root(){return (LinearLayout)field(activity,"root");}
    private int index(){return (Integer)field(activity,"index");}
    private void waitFor(java.util.function.BooleanSupplier condition){long until=SystemClock.elapsedRealtime()+15000;while(SystemClock.elapsedRealtime()<until){boolean[] done={false};ui(()->done[0]=condition.getAsBoolean());if(done[0])return;SystemClock.sleep(30);}throw new AssertionError("Timed out waiting for study UI");}
    private void ready(){waitFor(()->!(Boolean)field(activity,"busy")&&((List<?>)field(activity,"words")).size()>1);waitForIdleSync();}
    private View label(View v,String text){if(v instanceof TextView&&((TextView)v).getText().toString().equals(text))return v;if(v instanceof ViewGroup)for(int i=0;i<((ViewGroup)v).getChildCount();i++){View found=label(((ViewGroup)v).getChildAt(i),text);if(found!=null)return found;}return null;}
    private View label(String text){View v=label(root(),L.t(text));if(v==null)throw new AssertionError("Missing "+text);return v;}
    private ScrollView scroll(View v){if(v instanceof ScrollView)return (ScrollView)v;if(v instanceof ViewGroup)for(int i=0;i<((ViewGroup)v).getChildCount();i++){ScrollView found=scroll(((ViewGroup)v).getChildAt(i));if(found!=null)return found;}return null;}
    private void send(int action,float x,float y){if(action==MotionEvent.ACTION_DOWN)down=SystemClock.uptimeMillis();int[] origin=new int[2];root().getLocationOnScreen(origin);MotionEvent e=MotionEvent.obtain(down,SystemClock.uptimeMillis(),action,x+origin[0],y+origin[1],0);e.offsetLocation(-origin[0],-origin[1]);root().dispatchTouchEvent(e);e.recycle();}
    private float[] center(View v){int[] a=new int[2],b=new int[2];v.getLocationOnScreen(a);root().getLocationOnScreen(b);return new float[]{a[0]-b[0]+v.getWidth()/2f,a[1]-b[1]+v.getHeight()/2f};}
    private void gesture(String area){
        View start=area.equals("top")?((ViewGroup)root().getChildAt(0)).getChildAt(0):area.equals("font")?label("Aa"):area.equals("favorite")?((View)field(activity,"status")).getRootView():area.equals("status")?(View)field(activity,"status"):area.equals("meaning")?label("点击揭晓释义"):area.equals("read")?label("朗读"):label("‹ 上一个");
        if(area.equals("favorite")){View mark=label(root(),L.t("收藏"));if(mark==null)mark=label(root(),L.t("已收藏"));start=mark;}
        float[] c=center(start);float x=Math.max(Ui.dp(activity,65),c[0]),y=c[1];int before=index(),total=((List<?>)field(activity,"words")).size();float distance=Ui.dp(activity,55);
        send(MotionEvent.ACTION_DOWN,x,y);check((Boolean)field(activity,"touchingSurface"),"Touch anywhere suppresses automatic cycling: "+area);send(MotionEvent.ACTION_MOVE,x-distance,y+1);send(MotionEvent.ACTION_UP,x-distance,y+1);check(index()==(before+1)%total,"Whole-page left swipe advances once: "+area);check(!(Boolean)field(activity,"touchingSurface")&&!activity.isFinishing(),"Swipe releases touch and does not click: "+area);
        send(MotionEvent.ACTION_DOWN,x-distance,y);send(MotionEvent.ACTION_MOVE,x,y+1);send(MotionEvent.ACTION_UP,x,y+1);check(index()==before,"Whole-page right swipe returns once: "+area);
    }
    private void verifyText(View v){if(v.getVisibility()!=View.VISIBLE)return;if(v instanceof TextView){TextView text=(TextView)v;if(text.getText().length()>0&&text.getLayout()!=null)check(text.getHeight()+2>=text.getLayout().getHeight()+text.getCompoundPaddingTop()+text.getCompoundPaddingBottom(),"Visible text has sufficient measured height: "+text.getText());}if(v instanceof ViewGroup)for(int i=0;i<((ViewGroup)v).getChildCount();i++)verifyText(((ViewGroup)v).getChildAt(i));}
    private void gaps(LinearLayout row){for(int i=1;i<row.getChildCount();i++)check(row.getChildAt(i).getLeft()-row.getChildAt(i-1).getRight()>=Ui.dp(activity,4),"Action buttons retain a visible gap");for(int i=0;i<row.getChildCount();i++)check(row.getChildAt(i).getHeight()>=Ui.dp(activity,44),"Action touch height is preserved");}
    private void two(int action,float x,float y){MotionEvent.PointerProperties[] props=new MotionEvent.PointerProperties[2];MotionEvent.PointerCoords[] coords=new MotionEvent.PointerCoords[2];for(int i=0;i<2;i++){props[i]=new MotionEvent.PointerProperties();props[i].id=i;props[i].toolType=MotionEvent.TOOL_TYPE_FINGER;coords[i]=new MotionEvent.PointerCoords();coords[i].x=x+i*12;coords[i].y=y;coords[i].pressure=1;coords[i].size=1;}MotionEvent e=MotionEvent.obtain(down,SystemClock.uptimeMillis(),action,2,props,coords,0,0,1,1,0,0,InputDevice.SOURCE_TOUCHSCREEN,0);root().dispatchTouchEvent(e);e.recycle();}
    @Override public void onStart(){Bundle result=new Bundle();try{
        if(!Build.HARDWARE.equals("ranchu")&&!Build.HARDWARE.equals("goldfish"))throw new AssertionError("Disposable emulator only");Context c=getTargetContext();Prefs prefs=new Prefs(c);prefs.data.edit().putString("uiLanguage",language).putBoolean("languagePromptSeen",true).putBoolean("languagePromptPending",false).putString("level","N5").putString("frequency","ALL").putString("groupMode","OFF").putString("studyMode","all").putBoolean("hideFamiliar",false).putBoolean("shuffle",false).putBoolean("conceal",true).putBoolean("autoSpeak",false).putBoolean("speakOnFlip",false).putString("voiceEngine",c.getPackageName()+".test").commit();
        activity=(BrowseActivity)startActivitySync(new Intent(c,BrowseActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK|Intent.FLAG_ACTIVITY_CLEAR_TASK));ready();waitFor(()->((Speech)field(activity,"speech")).isReady());
        ui(()->{check(root() instanceof SwipeCardLayout,"Gesture surface spans the entire browsing page");check(((TextView)field(activity,"status")).getText().toString().equals(L.t("日语语音已就绪")),"Ready state uses a short status");check(((View)field(activity,"audioSettings")).getVisibility()==View.GONE,"Ready engine hides recovery action");gaps((LinearLayout)root().getChildAt(0));gaps((LinearLayout)root().getChildAt(root().getChildCount()-1));View mark=label(root(),L.t("收藏"));if(mark==null)mark=label(root(),L.t("已收藏"));gaps((LinearLayout)mark.getParent());verifyText(root());});
        for(String area:new String[]{"top","font","meaning","read","previous"}){final String a=area;ui(()->gesture(a));waitForIdleSync();}
        int[] tapped={0};ui(()->{View meaning=label("点击揭晓释义");tapped[0]=index();float[] pos=center(meaning);send(MotionEvent.ACTION_DOWN,pos[0],pos[1]);two(MotionEvent.ACTION_POINTER_DOWN|(1<<MotionEvent.ACTION_POINTER_INDEX_SHIFT),pos[0],pos[1]);two(MotionEvent.ACTION_POINTER_UP|(1<<MotionEvent.ACTION_POINTER_INDEX_SHIFT),pos[0],pos[1]);send(MotionEvent.ACTION_UP,pos[0],pos[1]);});waitForIdleSync();ui(()->check(index()==tapped[0]&&!(Boolean)field(activity,"revealed"),"Early second finger never activates the meaning click"));
        ui(()->{View meaning=label("点击揭晓释义");float[] pos=center(meaning);send(MotionEvent.ACTION_DOWN,pos[0],pos[1]);send(MotionEvent.ACTION_UP,pos[0],pos[1]);});waitForIdleSync();ui(()->check(index()==tapped[0]&&(Boolean)field(activity,"revealed"),"Ordinary meaning tap still reveals without navigation"));
        ui(()->{ScrollView body=scroll(root());int before=index();float[] pos=center(body);float x=pos[0],y=pos[1];send(MotionEvent.ACTION_DOWN,x,y);send(MotionEvent.ACTION_MOVE,x,y-Ui.dp(activity,55));send(MotionEvent.ACTION_MOVE,x-Ui.dp(activity,90),y-Ui.dp(activity,115));send(MotionEvent.ACTION_UP,x-Ui.dp(activity,90),y-Ui.dp(activity,115));check(index()==before&&!(Boolean)field(activity,"touchingSurface"),"Established vertical scrolling is never stolen by sideways movement");body.scrollTo(0,body.getChildAt(0).getHeight());});waitForIdleSync();
        for(String area:new String[]{"favorite","status"}){final String a=area;ui(()->gesture(a));waitForIdleSync();ui(()->{ScrollView s=scroll(root());s.scrollTo(0,s.getChildAt(0).getHeight());});waitForIdleSync();}
        ui(()->{float x=root().getWidth()/2f,y=center(label("朗读"))[1],dist=Ui.dp(activity,60);for(int i=0;i<20;i++){int before=index();send(MotionEvent.ACTION_DOWN,x,y);send(MotionEvent.ACTION_MOVE,x-dist,y);send(MotionEvent.ACTION_CANCEL,x-dist,y);check(index()==before&&!(Boolean)field(activity,"touchingSurface"),"Cancellation never flips or leaves touch held");send(MotionEvent.ACTION_DOWN,x,y);send(MotionEvent.ACTION_MOVE,x-dist,y);two(MotionEvent.ACTION_POINTER_DOWN|(1<<MotionEvent.ACTION_POINTER_INDEX_SHIFT),x-dist,y);two(MotionEvent.ACTION_MOVE,x-dist*1.5f,y);two(MotionEvent.ACTION_POINTER_UP|(1<<MotionEvent.ACTION_POINTER_INDEX_SHIFT),x-dist*1.5f,y);send(MotionEvent.ACTION_UP,x-dist*1.5f,y);check(index()==before&&!(Boolean)field(activity,"touchingSurface"),"Multiple fingers cancel navigation");}activity.finish();});waitForIdleSync();
        // 无声音时从学习页直达设置；返回后重新检测而不自动播放。 / Open settings for a missing engine; recheck on return without autoplay.
        prefs.put("voiceEngine","missing.cijian.engine");activity=(BrowseActivity)startActivitySync(new Intent(c,BrowseActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK|Intent.FLAG_ACTIVITY_CLEAR_TASK));ready();waitFor(()->!((Speech)field(activity,"speech")).isInitializing());int[] before={0};ActivityMonitor monitor=addMonitor(MainActivity.class.getName(),null,false);ui(()->{before[0]=index();View settings=(View)field(activity,"audioSettings");check(settings.getVisibility()==View.VISIBLE&&settings.getHeight()>=Ui.dp(activity,44),"Missing engine exposes accessible compact settings action");settings.performClick();});MainActivity main=(MainActivity)waitForMonitorWithTimeout(monitor,8000);check(main!=null,"Recovery action opens MainActivity");waitForIdleSync();ui(()->{check((Integer)field(main,"tab")==3&&(Integer)field(main,"settingsCategory")==4,"Recovery lands directly in voice settings");TextView state=(TextView)field(main,"voiceStatus");check(state.getLineSpacingMultiplier()>=1.15f,"Detailed status uses readable line spacing");View back=label(main.getWindow().getDecorView(),L.t("‹ 返回学习"));check(back!=null,"Shortcut settings exposes direct study return");prefs.put("voiceEngine",c.getPackageName()+".test");if(language.equals("ZH"))back.performClick();else main.onBackPressed();});waitForIdleSync();removeMonitor(monitor);waitFor(()->(Boolean)field(activity,"foreground")&&((Speech)field(activity,"speech")).isReady());ui(()->{check(index()==before[0],"Returning from voice settings keeps the word");check((Boolean)field(activity,"paused")&&!((Speech)field(activity,"speech")).isSpeakingSequence(),"Recovery returns paused and silent");check(((View)field(activity,"audioSettings")).getVisibility()==View.GONE,"Successful recheck removes recovery action");activity.finish();});
        result.putString("stream","PASS: "+checks+" full-page gesture, spacing and voice-recovery checks in "+language+"\n");finish(Activity.RESULT_OK,result);
    }catch(Throwable e){result.putString("stream","FAIL: "+android.util.Log.getStackTraceString(e));finish(Activity.RESULT_CANCELED,result);}}
}
